<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/registration.php';require_once __DIR__.'/../includes/email_templates.php';require_guest();
$db=db();$onboarding=registration_current($db);
if(!$onboarding){flash('Sign in to view your subscription status. Your account is preserved.');redirect_to('auth/login.php');}
if(!$onboarding['initial_submission_id']){redirect_to('auth/registration_payment.php');}
$payment=subscription_query($db,'SELECT * FROM subscription_payments WHERE submission_id=? AND user_id=?',[$onboarding['initial_submission_id'],$onboarding['user_id']])->fetch();
if(!$payment){http_response_code(404);exit('Submission unavailable.');}
$method=json_decode($payment['method_snapshot'],true);$page_title='Registration Completed';$active_page='subscription';$registrationStep=3;require __DIR__.'/../includes/header.php';
?>
<main class="onboarding-shell"><div class="onboarding-brand"><a class="pp-wordmark" href="<?= e(app_url()) ?>"><img src="<?= e(app_url('assets/images/logo-icon.jpg')) ?>" width="42" height="42" alt="">ProfitPocket</a></div><?php require __DIR__.'/../includes/registration_progress.php'; ?><section class="subscription-card onboarding-confirmation"><span class="onboarding-success" aria-hidden="true">✓</span><h1>Registration Completed!</h1><p>Your ProfitPocket account has been created, and your ₱100 subscription payment has been submitted for verification.</p><?php if($payment['status']==='pending'): ?><p>Please wait for a System Administrator to review your payment. You will receive an email once your account has been activated.</p><?php elseif($payment['status']==='rejected'): ?><div class="alert alert-warning">Your proof needs correction: <?= e($payment['review_note']) ?> Sign in to submit corrected proof.</div><?php else: ?><div class="alert alert-success">Your payment has been approved. Sign in to open your business tools.</div><?php endif; ?><dl class="subscription-facts"><div><dt>Registered Email</dt><dd><?= e($onboarding['email']) ?></dd></div><div><dt>Selected Payment Method</dt><dd><?= e($method['method_name'].(!empty($method['bank_name'])?' · '.$method['bank_name']:'')) ?></dd></div><div><dt>Amount Submitted</dt><dd>₱100.00</dd></div><div><dt>Submission Date</dt><dd><?= e(email_date($payment['submitted_at'])) ?></dd></div><div><dt>Status</dt><dd><span class="subscription-status" data-state="<?= e($payment['status']) ?>"><?= $payment['status']==='pending'?'Pending Verification':e(subscription_label($payment['status'])) ?></span></dd></div></dl><p class="form-text mt-4">Your account will become fully accessible once your subscription payment has been approved.</p><a class="btn btn-primary w-100" href="<?= e(app_url('auth/login.php')) ?>">Go to Sign In</a></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
